def test_dotted_only_exclude_nested_schema_instance():
    class Child(Schema):
        name = fields.String()
        age = fields.Integer()

    class Parent2(Schema):
        favorite = fields.Nested(Child(only=("name", "age")))
        children = fields.List(fields.Nested(Child(only=("name", "age"))))

    family = {
        "favorite": {"name": "Lily", "age": 15},
